/* Token Radar — dark terminal theme. No webfonts, no images, no network. */
:root {
  --bg: #07090d;
  --panel: #0d1117;
  --panel-2: #11161f;
  --line: #1e2632;
  --line-soft: #161d27;
  --text: #d7dee8;
  --muted: #8494a7;
  --faint: #5b6b7f;
  --accent: #3fb96f;
  --accent-dim: #1d3a28;
  --amber: #d9a13b;
  --red: #d95f4b;
  --mono: ui-monospace, "SF Mono", "Cascadia Mono", Menlo, Consolas, monospace;
}
* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 14px/1.5 -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}
.skip { position: absolute; left: -999px; top: 0; background: var(--accent); color: #04140a; padding: 6px 12px; }
.skip:focus { left: 8px; top: 8px; }
.shell { max-width: 1240px; margin: 0 auto; padding: 18px 20px 40px; }
.num { font-family: var(--mono); font-variant-numeric: tabular-nums; white-space: nowrap; }
.sub { color: var(--muted); font-size: 12px; }
.pos { color: var(--accent); }
.neg { color: var(--red); }

/* header */
.top { display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 6px 0 14px; border-bottom: 1px solid var(--line); flex-wrap: wrap; }
.brand { display: flex; align-items: center; gap: 10px; }
.mark { width: 12px; height: 12px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 4px var(--accent-dim), 0 0 14px var(--accent); }
.brand-name { font-family: var(--mono); font-weight: 700; letter-spacing: 2px; font-size: 16px; }
.top-meta { display: flex; gap: 18px; color: var(--muted); font-family: var(--mono); font-size: 12px; flex-wrap: wrap; }
.top-meta b { color: var(--text); font-weight: 600; }

/* lede + facts */
.lede { display: grid; grid-template-columns: 1fr; gap: 14px; padding: 18px 0 4px; }
.lede h1 { font-size: 24px; line-height: 1.25; margin: 0 0 6px; font-weight: 650; }
.lede h1 .hl { color: var(--accent); }
.lede p { margin: 0; color: var(--muted); max-width: 76ch; }
.facts { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; }
.fact { background: var(--panel); border: 1px solid var(--line-soft); border-radius: 8px; padding: 10px 12px; }
.fact span { display: block; color: var(--faint); font-size: 11px; text-transform: uppercase; letter-spacing: 1px; }
.fact b { font-family: var(--mono); font-size: 19px; font-weight: 650; }

/* panels */
.panel { background: var(--panel); border: 1px solid var(--line-soft); border-radius: 10px; margin-top: 14px; }
.panel > h2, .panel .panel-head { padding: 12px 16px 0; }
.panel h2 { font-size: 15px; margin: 0; }
.panel .body { padding: 8px 16px 14px; }

/* methodology */
.formula { font-family: var(--mono); font-size: 13px; background: var(--panel-2); border: 1px solid var(--line); border-radius: 8px; padding: 10px 12px; margin: 10px 0; overflow-x: auto; white-space: nowrap; }
.mult-table { width: 100%; border-collapse: collapse; font-size: 12.5px; }
.mult-table th, .mult-table td { text-align: left; padding: 4px 8px; border-bottom: 1px solid var(--line-soft); }
.mult-table th { color: var(--faint); font-weight: 600; text-transform: uppercase; font-size: 11px; letter-spacing: 0.5px; }
.mult-table td.n, .mult-table th.n { text-align: right; font-family: var(--mono); }
.method-notes { color: var(--muted); font-size: 12.5px; }
.method-notes li { margin: 3px 0; }

/* controls */
.controls { display: flex; gap: 12px; align-items: end; flex-wrap: wrap; margin-top: 16px; }
.field { display: flex; flex-direction: column; gap: 4px; }
.field label, .field .sub { font-size: 11px; text-transform: uppercase; letter-spacing: 1px; color: var(--faint); }
.field input, .field select {
  background: var(--panel-2); color: var(--text); border: 1px solid var(--line);
  border-radius: 6px; padding: 7px 10px; font-size: 13px; min-width: 150px;
}
.field input:focus, .field select:focus { outline: 2px solid var(--accent); outline-offset: 0; }
.tabs { display: flex; border: 1px solid var(--line); border-radius: 6px; overflow: hidden; }
.tabs button { background: var(--panel-2); color: var(--muted); border: 0; padding: 7px 14px; font-size: 13px; cursor: pointer; }
.tabs button[aria-pressed="true"] { background: var(--accent-dim); color: var(--accent); font-weight: 650; }
.count { margin-left: auto; color: var(--muted); font-family: var(--mono); font-size: 12px; padding-bottom: 8px; }

/* board table */
.table-wrap { overflow-x: auto; }
table.board { width: 100%; border-collapse: collapse; font-size: 13px; }
table.board caption { text-align: left; padding: 10px 16px 4px; }
table.board th, table.board td { padding: 7px 10px; border-bottom: 1px solid var(--line-soft); text-align: left; vertical-align: middle; }
table.board thead th { color: var(--faint); font-size: 11px; text-transform: uppercase; letter-spacing: 0.5px; border-bottom: 1px solid var(--line); }
table.board thead th button { background: none; border: 0; color: inherit; font: inherit; text-transform: inherit; letter-spacing: inherit; cursor: pointer; padding: 0; }
table.board th.r, table.board td.r { text-align: right; }
table.board tbody tr { cursor: pointer; }
table.board tbody tr:hover { background: var(--panel-2); }
table.board tbody tr[data-selected="true"] { background: var(--accent-dim); }
.name b { font-weight: 620; }
.name .sub { display: block; }
.chains { color: var(--muted); font-size: 12px; }
.bar { height: 4px; background: var(--line); border-radius: 2px; margin-top: 4px; min-width: 90px; }
.bar i { display: block; height: 100%; background: var(--accent); border-radius: 2px; }
.chip { font-family: var(--mono); font-size: 11px; padding: 2px 8px; border-radius: 20px; border: 1px solid var(--line); white-space: nowrap; }
.chip.high { color: var(--accent); border-color: var(--accent-dim); background: var(--accent-dim); }
.chip.med { color: var(--amber); }
.chip.low { color: var(--faint); }
.status { font-family: var(--mono); font-size: 11px; color: var(--amber); white-space: nowrap; }
.status.live { color: var(--muted); }
.empty { padding: 28px 16px; text-align: center; color: var(--muted); }
.button { background: var(--accent); color: #04140a; border: 0; border-radius: 6px; padding: 8px 16px; font-weight: 650; cursor: pointer; margin-top: 10px; }

/* detail dialog */
dialog.detail { background: var(--panel); color: var(--text); border: 1px solid var(--line); border-radius: 12px; width: min(680px, 94vw); max-height: 88vh; padding: 0; }
dialog.detail::backdrop { background: rgba(0, 0, 0, 0.7); }
.detail-head { display: flex; justify-content: space-between; gap: 12px; padding: 16px 20px 10px; border-bottom: 1px solid var(--line-soft); }
.detail-head h2 { margin: 2px 0; font-size: 21px; }
.close { background: var(--panel-2); color: var(--text); border: 1px solid var(--line); border-radius: 6px; height: 32px; padding: 0 12px; cursor: pointer; }
.detail-section { padding: 12px 20px 4px; }
.detail-section h3 { font-size: 12px; text-transform: uppercase; letter-spacing: 1px; color: var(--faint); margin: 6px 0 8px; }
.equation { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 8px; }
.equation > div { background: var(--panel-2); border: 1px solid var(--line-soft); border-radius: 8px; padding: 8px 10px; }
.equation span { display: block; color: var(--faint); font-size: 11px; text-transform: uppercase; letter-spacing: 0.5px; }
.equation b { font-size: 15px; }
.equation .total { border-color: var(--accent-dim); }
.equation .total b { color: var(--accent); }
ol.steps { margin: 0 0 14px; padding-left: 20px; }
ol.steps li { margin: 8px 0; }
ol.steps .cost { display: block; color: var(--muted); font-size: 12px; font-family: var(--mono); }
footer.note { color: var(--faint); font-size: 12px; margin-top: 18px; }
@media (max-width: 720px) {
  .lede h1 { font-size: 20px; }
  .count { margin-left: 0; }
}
```

